insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_naraj_maragath','Naraj Mahanadi Barrage & Peacock Valley','Odisha','Cuttack','River','Naraj is the scenic vantage point where the mighty Mahanadi River splits into its main deltaic branch, the Kathajodi River. Featuring a sprawling barrage, ancient Buddhist rock carvings at Siddheswar hill, and the famous Siddheswar Peacock Valley sanctuary where dozens of wild peacocks feed daily.','20.4667','85.7667','needs_review','Year-round (Best at 4 PM for peacock feeding)','1',array['river','barrage','peacocks','sunset spot','road trip','low cost escape','photography']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_charchika','Charchika Temple Banki','Odisha','Cuttack','Temple','Maa Charchika Temple in Banki town is one of Odisha''s oldest Shakti shrines, dedicated to eight-armed Goddess Chamunda (Charchika). Perched on the small Ruchika hill on the banks of Renuka River (tributary of Mahanadi), it draws huge crowds during Durga Puja.','20.3833','85.5333','needs_review','October – March (Durga Puja in Oct)','1',array['temple','shakti peetha','river','heritage','day trip','low cost escape']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
