insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_choudwar_otm','Choudwar & Kalinga War Memorial','Odisha','Cuttack','Scenic drive','Located across the Birupa River north of Cuttack city, Choudwar was the ancient capital of Somavamsi rulers before shifting to Cuttack. Today known for its scenic Birupa barrage, calm river roads, and ancient Baideswar Shiva temple ruins.','20.5333','85.9','needs_review','October – March','1',array['industrial heritage','river','road trip','cuttack','low cost escape']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_gopalpur','Gopalpur-on-Sea Beach','Odisha','Ganjam','Beach','Gopalpur-on-Sea was an important seaport during the East India Company era for shipping rice to Burma. Today it is Odisha''s premier quiet beach resort town, featuring fine golden sands, gentle surf, a historical 1871 lighthouse, coconut palms, and heritage beach bungalows.','19.2644','84.9125','needs_review','October – March','2',array['beach','sea','heritage port','lighthouse','resort','weekend','peaceful']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
