insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_taratarini','Tara Tarini Hilltop Temple','Odisha','Ganjam','Temple','Tara Tarini Temple is one of the four major ancient Tantric Shakti Peethas of India, dedicated to twin goddesses Tara and Tarini. Perched atop the scenic Purna Giri hill on the banks of Rushikulya River, pilgrims ascend via a 999-step staircase, a winding road, or a scenic cable car ropeway.','19.4917','84.9','needs_review','October – March (Chaitra Yatra in Mar/Apr)','1',array['temple','shakti peetha','hilltop','ropeway','viewpoint','spiritual']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
