insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_tampara','Tampara Lake & Water Sports Complex','Odisha','Ganjam','Lake','Tampara is a beautiful 5.8 km long freshwater lake parallel to the Bay of Bengal coastline near Chatrapur. OTDC has transformed it into a modern water sports resort featuring jet skis, banana rides, speedboats, kayaking, eco-cottages, and a lighted lakeside promenade.','19.35','84.9833','needs_review','October – March','1',array['lake','water sports','boating','picnic','resort','nature']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
