insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_rushikulya','Rushikulya Olive Ridley Turtle Rookery','Odisha','Ganjam','Wildlife','Rushikulya river mouth beach is one of the world''s premier mass nesting sites for Olive Ridley sea turtles (Lepidochelys olivacea). Every year between February and March, the phenomenon of ''Arribada'' occurs as over 300,000 to 500,000 female sea turtles emerge simultaneously under night skies to lay millions of eggs.','19.3833','85.0667','needs_review','February – May (Nesting Feb/Mar, Hatching Apr/May)','1',array['turtles','olive ridley','arribada','beach','wildlife','conservation','nature']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
