insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_simlipal','Simlipal National Park & Tiger Reserve','Odisha','Mayurbhanj','Wildlife','Simlipal is Odisha''s flagship wilderness—a UNESCO World Network Biosphere Reserve spanning 2,750 sq km of dense sal forests, rolling plateaus, and 1,076 species of plants. Home to the world''s only wild melanistic (black) tigers, Bengal tigers, 500+ elephants, leopards, and thunderous waterfalls Barehipani and Joranda.','21.9333','86.35','needs_review','November – June (Park closed July–October for monsoon)','3',array['national park','tiger reserve','waterfall','wildlife','safari','forest','unesco biosphere']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
