insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_gupteswar','Gupteswar Cave Temple & Sabari River','Odisha','Koraput','Heritage','Gupteswar (''Hidden God'') is a natural limestone cave temple hidden deep inside Ramagiri forest on the banks of Sabari River. The cave houses a massive natural stalagmite Shiva Lingam that continuously grows in size. Pilgrims climb 200 steps through lush jungle to enter the cool, damp cavern.','18.8167','82.3','needs_review','October – March (Maha Shivratri in Feb/Mar)','1',array['cave','temple','shiva','forest','river','spiritual']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
