insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_hirakud','Hirakud Dam & Reservoir','Odisha','Sambalpur','Lake','Built in 1957 across the Mahanadi River, Hirakud Dam is a triumph of post-independence engineering—the world''s longest earthen dam stretching 25.8 km. The vast 743 sq km reservoir forms a inland sea home to migratory waterbirds, surrounded by Debrigarh forest.','21.5333','83.8667','needs_review','October – March','1',array['dam','longest dam','reservoir','viewpoint','debrigarh','road trip']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
