insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_huma','Huma Leaning Temple of Lord Bimaleswar','Odisha','Sambalpur','Heritage','Built in 1670 AD by King Baliar Singh of Sambalpur, Huma is the world''s only known leaning temple complex. The main temple, inner sanctum, and surrounding sub-shrines all tilt at a noticeable angle toward the Mahanadi riverbed. The river ghat is famous for friendly, tame ''Kudo'' fish that eat grain directly from visitors'' hands.','21.2833','83.9833','needs_review','October – March','1',array['leaning temple','architecture','mystery','river','fish','unique']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
