insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_panchalingeswar','Panchalingeswar Temple & Nilagiri Hills','Odisha','Balasore','Temple','Panchalingeswar (''Five Lingams'') is situated on the verdant Nilagiri hills. Five natural stone Shiva Lingams remain permanently submerged beneath a clear perennial hill stream. Devotees lie flat on rock beds to touch and worship the Lingams underwater as the cool hill stream flows over their hands.','21.4167','86.7167','needs_review','October – March','1',array['temple','waterfall','hill','shiva','perennial stream','nature']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
