insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_satkosia','Satkosia Tiger Reserve & Mahanadi Gorge','Odisha','Angul','Wildlife','Satkosia (''Seven Miles'') Gorge is where the mighty Mahanadi River cuts through a spectacular 22 km long mountain gorge flanked by dense forests of Satkosia Tiger Reserve. Famous for Tikarpada Crocodile Sanctuary, gharials, muggers, river boat safaris, and luxury eco-tents pitched on golden river sandbars.','20.6167','84.85','needs_review','November – April','2',array['tiger reserve','gorge','mahanadi','boating','wildlife','tents','nature']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
